import sys

def correct_word(s):
    vowels = set('aeiouy')
    result = []

    for char in s:
        if result and result[-1] in vowels and char in vowels:
            continue
        result.append(char)

    return ''.join(result)

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])  # number of letters in word s
    s = data[1]       # the word before the correction

    corrected_word = correct_word(s)
    print(corrected_word)

if __name__ == "__main__":
    main()

